from collections import deque
def shortestPathLength(graph):
    n = len(graph)
    if n <= 1:
        return 0
    target = (1 << n) - 1
    q = deque()
    visited = set()
    for i in range(n):
        mask = 1 << i
        q.append((i, mask, 0))
        visited.add((i, mask))
    while q:
        u, mask, dist = q.popleft()
        if mask == target:
            return dist
        for v in graph[u]:
            next_mask = mask | (1 << v)
            if (v, next_mask) not in visited:
                visited.add((v, next_mask))
                q.append((v, next_mask, dist + 1))
    return 0
